create extension if not exists pgcrypto;
create type integration_provider as enum ('tokko','wordpress','resend');
create type integration_status as enum ('pending','connected','error','disabled');
create type automation_type as enum ('weekly_new_properties','monthly_properties','monthly_blog');
create type campaign_status as enum ('draft','ready','scheduled','sending','sent','failed','cancelled');
create table sites (id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,business_type text,domain text,wordpress_url text,logo_url text,primary_color text not null,secondary_color text not null,sender_name text,sender_email text,timezone text not null default 'America/Lima',is_active boolean not null default true,tokko_filter jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table site_integrations (id uuid primary key default gen_random_uuid(),site_id uuid not null references sites on delete cascade,provider integration_provider not null,status integration_status not null default 'pending',config jsonb not null default '{}',last_sync_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(site_id,provider));
create table properties (id uuid primary key default gen_random_uuid(),site_id uuid references sites on delete set null,external_id text not null unique,title text not null,description text,property_type text,location text,address text,price numeric,currency text,area numeric,image_url text,public_url text,status text,published_at timestamptz,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),source_data jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table blog_posts (id uuid primary key default gen_random_uuid(),site_id uuid not null references sites on delete cascade,external_id text not null,title text not null,excerpt text,image_url text,public_url text,published_at timestamptz,source_data jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(site_id,external_id));
create table automation_settings (id uuid primary key default gen_random_uuid(),site_id uuid not null references sites on delete cascade,type automation_type not null,is_enabled boolean not null default true,frequency text not null,day_of_week smallint,day_of_month smallint,send_time time not null default '09:00',requires_approval boolean not null default true,last_run_at timestamptz,next_run_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(site_id,type));
create table campaigns (id uuid primary key default gen_random_uuid(),site_id uuid not null references sites on delete cascade,automation_type automation_type not null,name text not null,subject text not null,status campaign_status not null default 'draft',recipient_count integer not null default 0,scheduled_at timestamptz,sent_at timestamptz,resend_broadcast_id text,error_message text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table campaign_items (id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaigns on delete cascade,item_type text not null check(item_type in ('property','blog_post')),item_id uuid not null,position integer not null,created_at timestamptz not null default now(),unique(campaign_id,item_type,item_id));
create table sync_logs (id uuid primary key default gen_random_uuid(),site_id uuid references sites on delete set null,provider integration_provider not null,operation text not null,status text not null check(status in ('success','warning','error')),started_at timestamptz not null,finished_at timestamptz,items_received integer not null default 0,items_created integer not null default 0,items_updated integer not null default 0,error_message text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index properties_site_status_idx on properties(site_id,status); create index campaigns_site_status_idx on campaigns(site_id,status); create index sync_logs_created_idx on sync_logs(created_at desc);
